class Solution:
    def calculateScore(self, s: str) -> int:
        mirror_map = {chr(i): chr(125 - i) for i in range(26)}
        score = 0
        marked = [False] * len(s)

        for i in range(len(s)):
            char = s[i]
            mirror_char = mirror_map[char]

            for j in range(i):
                if not marked[j] and s[j] == mirror_char:
                    score += (i - j)
                    marked[j] = True
                    marked[i] = True
                    break

        return score
